CREATE TRIGGER trg_secret_nodes_cache_epoch
AFTER UPDATE ON secret_nodes FOR EACH ROW
WHEN NEW.cache_epoch = OLD.cache_epoch
BEGIN
  UPDATE secret_nodes SET cache_epoch = OLD.cache_epoch + 1 WHERE id = NEW.id;
END;
